<section data-page-title="My Reviews" data-page-script="reviews.js"><div class="page-intro"><span class="eyebrow">Share experience</span><h2>Reviews and ratings</h2><p>Review completed stays and manage your previous feedback.</p></div><div id="alertBox" class="alert"></div><div class="grid grid-2"><div class="card"><h3>Write / Edit Review</h3><form id="reviewForm" class="form-grid one"><input type="hidden" name="id" id="reviewId"><div class="form-group"><label>Completed Booking</label><select class="select" name="booking_id" id="completedBookingSelect" required></select></div><div class="form-group"><label>Overall Rating</label><input class="input" type="number" name="overall_rating" min="1" max="5" required></div><div class="form-group"><label>Cleanliness Rating</label><input class="input" type="number" name="cleanliness_rating" min="1" max="5" required></div><div class="form-group"><label>Service Rating</label><input class="input" type="number" name="service_rating" min="1" max="5" required></div><div class="form-group"><label>Review Text</label><textarea class="input" name="review_text" rows="4" required></textarea></div><div class="action-row"><button class="btn btn-gradient" type="submit">Save Review</button><button class="btn btn-light" type="button" id="resetBtn">Reset</button></div></form></div><div class="card"><div class="section-head"><h3>My Reviews</h3><button class="btn btn-light" id="refreshBtn">Refresh</button></div><div id="reviewList" class="review-list"><div class="empty">Loading reviews...</div></div></div></div></section>